<?php require __DIR__.'/config/bootstrap.php'; if(current_user()) redirect(current_user()['role']==='admin'?'admin/dashboard.php':'student/dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){$error='Enter a valid name and email. Password must have at least 8 characters.';}else{try{$s=$pdo->prepare("INSERT INTO users(full_name,email,phone,password_hash,role) VALUES(?,?,?,?, 'student')");$s->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT)]);flash('Account created. Please log in.');redirect('login.php');}catch(PDOException $e){$error='That email may already be registered.';}}} $page_title='Register';require __DIR__.'/includes/header.php'; ?>
<div class="max-w-lg mx-auto bg-white p-7 rounded-xl shadow-sm border"><h1 class="text-2xl font-bold">Create student account</h1><?php if($error): ?><p class="text-red-600 mt-3"><?= e($error) ?></p><?php endif; ?><form method="post" class="space-y-4 mt-5"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label class="block">Full name<input required name="full_name" class="mt-1 w-full border rounded-lg p-3"></label><label class="block">Email<input required type="email" name="email" class="mt-1 w-full border rounded-lg p-3"></label><label class="block">Phone number<input name="phone" class="mt-1 w-full border rounded-lg p-3" placeholder="2547..."></label><label class="block">Password<input required minlength="8" type="password" name="password" class="mt-1 w-full border rounded-lg p-3"></label><button class="w-full bg-blue-700 text-white p-3 rounded-lg font-semibold">Register</button></form></div><?php require __DIR__.'/includes/footer.php'; ?>
